mapper.select:
SELECT
sa.id,
sa.apply_user_id,
sa.target_user_id,
sa.old_date,
sa.new_date,
sa.status,
sa.audit_user_id,
sa.audit_time,
sa.effect_time,
sa.reserve1,
sa.reserve2,
sa.creator,
sa.updater,
sa.create_time,
sa.update_time,
apply_user.name AS apply_user_name,    -- 申请人姓名
target_user.name AS target_user_name   -- 换班对象姓名
FROM shift_apply sa
LEFT JOIN inspect_user apply_user ON sa.apply_user_id = apply_user.id
LEFT JOIN inspect_user target_user ON sa.target_user_id = target_user.id



        AND sa.apply_user_id = #{reqVO.applyUserId}




        AND sa.target_user_id = #{reqVO.targetUserId}




        AND sa.old_date BETWEEN #{reqVO.oldDate[0]} AND #{reqVO.oldDate[1]}




        AND sa.new_date BETWEEN #{reqVO.newDate[0]} AND #{reqVO.newDate[1]}




        AND sa.status = #{reqVO.status}




        AND sa.audit_user_id = #{reqVO.auditUserId}




        AND sa.audit_time BETWEEN #{reqVO.auditTime[0]} AND #{reqVO.auditTime[1]}




        AND sa.effect_time BETWEEN #{reqVO.effectTime[0]} AND #{reqVO.effectTime[1]}




        AND sa.reserve1 = #{reqVO.reserve1}




        AND sa.reserve2 = #{reqVO.reserve2}




        AND sa.creator = #{reqVO.creator}




        AND sa.updater = #{reqVO.updater}




        AND sa.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}




        AND sa.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}



    AND sa.deleted = 0

ORDER BY sa.id DESC
